        .btn {
            display: inline-block;
            background-color: #d94125;
            color: white;
            padding: 12px 28px;
            border: none;
            border-radius: 4px;
            font-size: 16px;
            font-weight: bold;
            text-transform: uppercase;
            cursor: pointer;
            transition: all 0.3s;
            text-decoration: none;
            margin: 0 10px;
        }

        .btn:hover {
            background-color: #b8371f;
            transform: translateY(-2px);
