        .section-title::after {
            content: '';
            position: absolute;
            width: 100px;
            height: 3px;
            background-color: #d94125;
            bottom: -15px;
            left: 50%;
            transform: translateX(-50%);
        }

        .feature-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .feature-card {
            background-color: rgba(20, 25, 30, 0.8);
            border-radius: 8px;
            overflow: hidden;
            transition: transform 0.3s;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .feature-card:hover {
            transform: translateY(-10px);
        }

        .feature-img {
            height: 200px;
            overflow: hidden;
        }

        .feature-img img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s;
        }

        .feature-card:hover .feature-img img {
            transform: scale(1.1);
        }

        .feature-content {
            padding: 20px;
        }

        .feature-content h3 {
            font-size: 22px;
            margin-bottom: 10px;
            color: white;
        }

        .feature-content p {
            color: #b0b0b0;
            line-height: 1.6;
        }

        .maps {
            padding: 80px 20px;
            background-color: rgba(0, 0, 0, 0.7);
            max-width: 1400px;
            margin: 0 auto;
        }

        .map-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 20px;
        }

        .map-card {
            position: relative;
            height: 200px;
            border-radius: 8px;
            overflow: hidden;
            background-color: #1a1a1a;
        }

        .map-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s;
        }

        .map-overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            background: linear-gradient(transparent, rgba(0,0,0,0.8));
            padding: 15px;
            transform: translateY(100%);
            transition: transform 0.3s;
        }

        .map-card:hover .map-overlay {
            transform: translateY(0);
        }

        .map-card:hover img {
            transform: scale(1.1);
        }

        .map-overlay h3 {
            color: white;
            margin-bottom: 5px;
        }

        .map-overlay p {
            color: #b0b0b0;
            font-size: 14px;
        }

        .news {
            padding: 80px 20px;
            max-width: 1400px;
            margin: 0 auto;
        }

        .news-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .news-card {
            background-color: rgba(20, 25, 30, 0.8);
            border-radius: 8px;
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .news-img {
            height: 180px;
            overflow: hidden;
        }

        .news-img img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s;
        }

        .news-card:hover .news-img img {
            transform: scale(1.1);
        }

        .news-content {
