            max-width: 600px;
            margin: 0 auto;
        }

        .newsletter h2 {
            margin-bottom: 20px;
            color: white;
        }

        .newsletter p {
            color: #b0b0b0;
            margin-bottom: 30px;
        }

        .newsletter-form {
