                top: 70px;
                left: 0;
                width: 100%;
                background-color: #000000;
                flex-direction: column;
                padding: 20px 0;
                border-bottom: 1px solid rgba(255, 255, 255, 0.1);
            }

            nav ul.show {
                display: flex;
            }

            nav ul li {
                margin: 10px 0;
                text-align: center;
            }

            .mobile-menu {
                display: block;
            }

            .hero h1 {
                font-size: 48px;
            }

            .hero p {
                font-size: 18px;
            }

            .section-title {
                font-size: 32px;
            }

            .tournament-card {
                flex-direction: column;
            }

            .tournament-img {
                flex: 0 0 auto;
                height: 200px;
            }

            .newsletter-form {
                flex-direction: column;
            }

            .newsletter-input {
                border-radius: 4px;
                margin-bottom: 10px;
